// ----- The archive axis -----

/** The runs the frame visits, in turn, and the one it rests on. */
export const VISITS = [0, 2, 6, 11]
export const REST_VISIT = 2
export const ARCHIVE_TODAY = '2026-11-19'

const parse = (iso: string) => iso.split('-').map(Number) as [number, number, number]
const daysIn = (y: number, m: number) => new Date(Date.UTC(y, m, 0)).getUTCDate()
const months = (iso: string) => {
	const [y, m, d] = parse(iso)
	return (y - 2025) * 12 + (m - 1) + (d - 1) / daysIn(y, m)
}
const SPAN = months(ARCHIVE_TODAY)
export const along = (iso: string) => months(iso) / SPAN
export const endOf = (r: Run) => along(r.stop ?? ARCHIVE_TODAY)
const utc = (iso: string) => Date.parse(`${iso}T00:00:00Z`)
export const daysLive = (run: Run) => Math.round((utc(run.stop ?? ARCHIVE_TODAY) - utc(run.start)) / 86_400_000)
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
export const short = (iso: string) => {
	const [y, m, d] = parse(iso)
	return `${MONTHS[m - 1]} ${d}${y === 2026 ? '' : `, ${y}`}`
}
export const between = (a: string, b: string) => {
	const ya = a.slice(0, 4)
	const same = ya === b.slice(0, 4) && ya !== '2026'
	return `${same ? short(a).replace(`, ${ya}`, '') : short(a)} to ${short(b)}`
}
export const runStatus = (r: Run) => (r.stop ? `Stopped ${short(r.stop)}` : 'Running')
export const runRange = (r: Run) => (r.stop ? between(r.start, r.stop) : `Since ${short(r.start)}`)
export const pct = (x: number) => `${(x * 100).toFixed(3)}%`
export const TICKS = [...['2025-01-01', '2025-04-01', '2025-07-01', '2025-10-01', '2026-01-01', '2026-04-01', '2026-07-01', '2026-10-01'].map((iso) => ({ at: along(iso), major: iso.endsWith('01-01') })), { at: 1, major: true }]
export const YEARS = [{ label: '2025', at: along('2025-01-01') }, { label: '2026', at: along('2026-01-01') }]
/** A run's bar in the 44-column server layout: its start column and its run of = signs. */
export const barCells = (run: Run) => {
	const a = Math.floor(along(run.start) * 44)
	const b = Math.max(a + 2, Math.round(endOf(run) * 44))
	return { a, b }
}

/** The archive axis's scene: the frame visits four runs in turn, the span and the readout following. */
export function buildArchive(runs: Run[]) {
	return function build(root: HTMLElement, tok: Tokens): Scene {
		const pics = [...root.querySelectorAll<HTMLElement>('[data-pic]')]
		const lanes = root.querySelector<HTMLElement>('[data-lanes]')!
		const bars = [...root.querySelectorAll<HTMLElement>('[data-bar]')]
		const ticks = [...root.querySelectorAll<HTMLElement>('[data-tick]')]
		const years = [...root.querySelectorAll<HTMLElement>('[data-year]')]
		const sel = root.querySelector<HTMLElement>('[data-span]')
		const days = root.querySelector('[data-days]')
		const stat = root.querySelector<HTMLElement>('[data-status]')
		const rng = root.querySelector('[data-range]')
		const fading = [...root.querySelectorAll<HTMLElement>('[data-fade]')]
		const step = tok.ms('--ds-loop-step', 2600)
		const change = tok.ms('--ds-loop-change', 700)
		const home = tok.ms('--ds-loop-flick', 1400)
		const easeLoop = tok.ease('--ds-easing-loop', [0.4, 0, 0.2, 1])
		const shown = VISITS.map((v) => ({ run: runs[v], v }))
		const W = lanes.clientWidth
		const x = (at: number) => Math.min(W - 1, Math.round(at * W))
		const cols = Math.floor(W / 8)
		const cellsOf = (r: Run) => {
			const a = Math.min(cols - 2, Math.floor(along(r.start) * cols))
			return { a, b: Math.min(cols, Math.max(a + 2, Math.round(endOf(r) * cols))) }
		}
		runs.forEach((run, i) => {
			const { a, b } = cellsOf(run)
			setStyle(bars[i], 'left', `${a * 8}px`)
			setText(bars[i], '='.repeat(b - a))
		})
		TICKS.forEach((t, i) => setStyle(ticks[i], 'left', `${x(t.at)}px`))
		YEARS.forEach((y, i) => setStyle(years[i], 'left', `${x(y.at)}px`))
		const spanOf = (r: Run) => {
			const { a, b } = cellsOf(r)
			return { a: a * 8, b: Math.min(W, b * 8) }
		}
		type Seg = { from: number; to: number; at: number; dur: number }
		const segs: Seg[] = []
		let at = 0
		VISITS.forEach((_, j) => {
			segs.push({ from: j, to: j, at, dur: step })
			at += step
			const next = (j + 1) % VISITS.length
			const dur = next === 0 ? home : change
			segs.push({ from: j, to: next, at, dur })
			at += dur
		})
		const loop = at
		const rest = segs[REST_VISIT * 2].at + step / 2
		let shownReadout = -1
		const readout = (j: number) => {
			if (j === shownReadout) return
			shownReadout = j
			const r = shown[j].run
			setText(days, String(daysLive(r)))
			setText(stat, runStatus(r))
			setData(stat, 'running', r.stop ? null : '')
			setText(rng, runRange(r))
		}
		const draw = (t: number) => {
			const seg = segs.find((sg) => t >= sg.at && t < sg.at + sg.dur) ?? segs[0]
			const p = span(t, seg.at, seg.at + seg.dur)
			const k = easeLoop(p)
			const moving = seg.from !== seg.to
			const now = moving && p >= 0.5 ? seg.to : seg.from
			const A = spanOf(shown[seg.from].run)
			const B = spanOf(shown[seg.to].run)
			const left = Math.round(lerp(A.a, B.a, moving ? k : 0))
			const right = Math.round(lerp(A.b, B.b, moving ? k : 0))
			setStyle(sel, 'left', `${left}px`)
			setStyle(sel, 'width', `${Math.max(1, right - left)}px`)
			bars.forEach((bar, i) => setData(bar, 'on', i === shown[now].v ? '' : null))
			readout(now)
			const words = moving ? Math.min(1, Math.abs(p - 0.5) / 0.25).toFixed(3) : '1'
			fading.forEach((el) => setStyle(el, 'opacity', words))
			pics.forEach((pic, i) => {
				const arriving = moving && i === seg.to
				const leaving = moving && i === seg.from
				const still = !moving && i === seg.from
				setStyle(pic, 'z-index', arriving ? '2' : leaving || still ? '1' : '0')
				setStyle(pic, 'opacity', arriving ? k.toFixed(3) : leaving || still ? '1' : '0')
			})
		}
		return { loop, rest, draw }
	}
}

// ----- The pricing meter -----

export const SERVER_COLS = 18
export function meterCells(calls: PricingCall[], cols: number) {
	const total = calls.reduce((sum, c) => sum + c.credits, 0)
	let sum = 0
	return calls.map((c) => {
		const a = Math.min(cols - 1, Math.round((sum / total) * cols))
		sum += c.credits
		const b = c.credits === 0 ? a : Math.min(cols, Math.max(a + 1, Math.round((sum / total) * cols)))
		return { a, b }
	})
}
export const fmt = (n: number) => n.toLocaleString('en-US')

/** The meter's scene: the month's calls arrive one by one, each charging its records, then the month turns over. */
export function buildMeter(calls: PricingCall[]) {
	const N = calls.length
	const LAST = N - 1
	const TOTAL = calls.reduce((sum, c) => sum + c.credits, 0)
	return function build(root: HTMLElement, tok: Tokens): Scene {
		const rows = [...root.querySelectorAll<HTMLElement>('[data-row]')]
		const bars = [...root.querySelectorAll<HTMLElement>('[data-bar]')]
		const nums = [...root.querySelectorAll<HTMLElement>('[data-credits]')]
		const total = root.querySelector<HTMLElement>('[data-total]')
		const lane = root.querySelector<HTMLElement>('[data-lane]')!
		const flick = tok.ms('--ds-loop-flick', 1400)
		const change = tok.ms('--ds-loop-change', 700)
		const fade = tok.ms('--ds-loop-badge', 500)
		const step = tok.ms('--ds-loop-step', 2600)
		const ease = tok.ease('--ds-easing-loop', [0.4, 0, 0.2, 1])
		const cols = Math.max(N, Math.floor(lane.clientWidth / 8))
		const cells = meterCells(calls, cols)
		cells.forEach(({ a }, i) => setStyle(bars[i], 'left', `${a * 8}px`))
		const startOf = (i: number) => i * flick
		const charged = startOf(LAST) + change
		const turn = charged + step
		const loop = turn + change
		const rest = charged + step / 2
		const before = calls.map((_, i) => calls.slice(0, i).reduce((sum, c) => sum + c.credits, 0))
		const draw = (t: number) => {
			if (t >= turn) {
				const p = span(t, turn, loop)
				const out = (1 - ease(p)).toFixed(3)
				rows.forEach((row) => setStyle(row, 'opacity', out))
				rows.forEach((row, i) => setData(row, 'on', i === LAST && p < 0.5 ? '' : null))
				setText(total, p < 0.5 ? fmt(TOTAL) : '0')
				setStyle(total, 'opacity', Math.min(1, Math.abs(p - 0.5) / 0.25).toFixed(3))
				return
			}
			setStyle(total, 'opacity', '1')
			const now = Math.min(LAST, Math.floor(t / flick))
			let sum = 0
			calls.forEach((call, i) => {
				const t0 = startOf(i)
				const shown = t >= t0
				setStyle(rows[i], 'opacity', shown ? ease(span(t, t0, t0 + fade)).toFixed(3) : '0')
				setData(rows[i], 'on', shown && i === now ? '' : null)
				const k = shown ? ease(span(t, t0, t0 + change)) : 0
				const { a, b } = cells[i]
				setText(bars[i], '='.repeat(Math.ceil((b - a) * k - 1e-6)))
				const c = Math.round(call.credits * k)
				setText(nums[i], String(c))
				if (shown) sum = before[i] + c
			})
			setText(total, fmt(sum))
		}
		return { loop, rest, draw }
	}
}

// ----- Built to be customized -----

export const CUSTOM_CELLS = 10

/** The tools' timeline: each tool's one lit cell goes dark in turn, then the last row fills, cell by cell. */
export function customTimeline(root: HTMLElement, m: Motion): Timeline {
	const duration = 2 * m.step
	const begin = m.fade + m.swap
	const show = { opacity: 1 }
	const hide = { opacity: 0 }
	const tracks: Track[] = []
	const cell = (el: Element, at: number) => {
		const dash = el.querySelector('[data-dash]')
		const hash = el.querySelector('[data-hash]')
		tracks.push({ el: hash, rest: show, frames: [...snap(m.swap, show, hide), ...snap(at, hide, show)] })
		tracks.push({ el: dash, rest: hide, frames: [...snap(m.swap, hide, show), ...snap(at, show, hide)] })
	}
	const rows = [...root.querySelectorAll('[data-tool]')]
	rows.forEach((row, i) => row.querySelectorAll('[data-cell]').forEach((el) => cell(el, begin + i * m.stagger)))
	const one = root.querySelector('[data-one]')
	const typed = begin + rows.length * m.stagger + m.change / 2
	one?.querySelectorAll('[data-cell]').forEach((el, k) => cell(el, typed + (k / CUSTOM_CELLS) * m.change))
	return { duration, tracks }
}

// The site's instrument clock (components/instrument/clock.ts), framework-free: a scene is built from a root's DOM
// and the brand tokens, then drawn at a time in its loop on each frame while at least half of it is on screen and the
// tab is visible. With reduced motion it draws its resting frame and stays there. Both flavors run the home's
// instruments (the archive axis, the pricing meter) with it.

export type Scene = { loop: number; rest: number; draw: (t: number) => void; dispose?: () => void }

export type Bezier = [number, number, number, number]

export type Tokens = {
	ms: (name: string, fallback: number) => number
	ease: (name: string, fallback: Bezier) => (x: number) => number
	px: (name: string, fallback: number) => number
	color: (name: string) => string
	font: (name: string) => string
}

/** A cubic-bezier curve as a function of progress. */
export function bezier([x1, y1, x2, y2]: Bezier) {
	const cx = 3 * x1
	const bx = 3 * (x2 - x1) - cx
	const ax = 1 - cx - bx
	const cy = 3 * y1
	const by = 3 * (y2 - y1) - cy
	const ay = 1 - cy - by
	const sx = (t: number) => ((ax * t + bx) * t + cx) * t
	const sy = (t: number) => ((ay * t + by) * t + cy) * t
	const dx = (t: number) => (3 * ax * t + 2 * bx) * t + cx
	return (x: number) => {
		if (x <= 0) return 0
		if (x >= 1) return 1
		let t = x
		for (let i = 0; i < 8; i++) {
			const err = sx(t) - x
			if (Math.abs(err) < 1e-5) return sy(t)
			const d = dx(t)
			if (Math.abs(d) < 1e-6) break
			t -= err / d
		}
		let lo = 0
		let hi = 1
		t = x
		for (let i = 0; i < 24; i++) {
			const v = sx(t)
			if (Math.abs(v - x) < 1e-5) break
			if (v < x) lo = t
			else hi = t
			t = (lo + hi) / 2
		}
		return sy(t)
	}
}

/** Reads time, easing, length, color and font tokens from an element's computed style. */
export function readTokens(el: Element): Tokens {
	const css = getComputedStyle(el)
	const v = (name: string) => css.getPropertyValue(name).trim()
	return {
		ms: (name, fallback) => {
			const raw = v(name)
			const n = parseFloat(raw)
			if (!Number.isFinite(n)) return fallback
			return raw.endsWith('ms') ? n : raw.endsWith('s') ? n * 1000 : n
		},
		ease: (name, fallback) => {
			const m = v(name).match(/cubic-bezier\(([^)]+)\)/)
			const nums = m?.[1].split(',').map(Number)
			return bezier(nums && nums.length === 4 && nums.every(Number.isFinite) ? (nums as Bezier) : fallback)
		},
		px: (name, fallback) => {
			const n = parseFloat(v(name))
			return Number.isFinite(n) ? n : fallback
		},
		color: (name) => v(name),
		font: (name) => v(name) || 'monospace',
	}
}

export const span = (t: number, a: number, b: number) => (b <= a ? (t >= b ? 1 : 0) : Math.min(1, Math.max(0, (t - a) / (b - a))))
export const lerp = (a: number, b: number, k: number) => a + (b - a) * k

export interface SceneOptions {
	/** Draw this time and stay there (a still for a screenshot). */
	freeze?: number
	/** Play whenever any of it is on screen, not only from half. */
	playWhileVisible?: boolean
}

/** Runs a scene on `root`; returns the function that stops it. */
export function startScene<T extends HTMLElement>(root: T, build: (root: T, tokens: Tokens) => Scene | Promise<Scene>, { freeze, playWhileVisible = false }: SceneOptions = {}): () => void {
	const reduce = window.matchMedia('(prefers-reduced-motion: reduce)')
	let scene: Scene | null = null
	let time = -1
	let last = 0
	let raf = 0
	let inView = false
	let near = false
	let alive = true
	let width = root.clientWidth
	let generation = 0

	const playing = () => scene && inView && !document.hidden && !reduce.matches && freeze === undefined

	const tick = (now: number) => {
		if (!scene) return
		const dt = last ? Math.min(now - last, 64) : 0
		last = now
		time += dt
		scene.draw(((time % scene.loop) + scene.loop) % scene.loop)
		raf = requestAnimationFrame(tick)
	}

	const sync = () => {
		cancelAnimationFrame(raf)
		last = 0
		if (!scene) return
		if (freeze !== undefined) scene.draw(freeze % scene.loop)
		else if (reduce.matches) scene.draw(scene.rest)
		else if (playing()) raf = requestAnimationFrame(tick)
		else scene.draw(((time % scene.loop) + scene.loop) % scene.loop)
	}

	const setup = async () => {
		if (!near) return
		const mine = ++generation
		const next = await build(root, readTokens(root))
		if (!alive || mine !== generation) {
			next.dispose?.()
			return
		}
		scene?.dispose?.()
		scene = next
		if (time < 0) time = next.rest
		sync()
	}

	const io = new IntersectionObserver(([entry]) => {
		inView = playWhileVisible ? entry.isIntersecting : entry.intersectionRatio >= 0.5
		sync()
	}, { threshold: [0, 0.5] })
	const approach = new IntersectionObserver(([entry]) => {
		if (!entry.isIntersecting) return
		approach.disconnect()
		near = true
		void setup()
	}, { rootMargin: '100% 0px' })
	let frame = 0
	const ro = new ResizeObserver(() => {
		if (root.clientWidth === width) return
		width = root.clientWidth
		cancelAnimationFrame(frame)
		frame = requestAnimationFrame(() => void setup())
	})

	approach.observe(root)
	io.observe(root)
	ro.observe(root)
	document.addEventListener('visibilitychange', sync)
	reduce.addEventListener('change', sync)
	return () => {
		alive = false
		approach.disconnect()
		io.disconnect()
		ro.disconnect()
		cancelAnimationFrame(raf)
		cancelAnimationFrame(frame)
		document.removeEventListener('visibilitychange', sync)
		reduce.removeEventListener('change', sync)
		scene?.dispose?.()
	}
}

export function setData(el: Element | null | undefined, name: string, value: string | null) {
	if (!el) return
	const attr = `data-${name}`
	if (value === null) {
		if (el.hasAttribute(attr)) el.removeAttribute(attr)
	} else if (el.getAttribute(attr) !== value) el.setAttribute(attr, value)
}

export function setStyle(el: HTMLElement | SVGElement | null | undefined, prop: string, value: string) {
	if (!el) return
	if (el.style.getPropertyValue(prop) !== value) el.style.setProperty(prop, value)
}

export function setText(el: Element | null | undefined, value: string) {
	if (el && el.textContent !== value) el.textContent = value
}

// The site's feature demo player (v2/V2Features Demo.tsx and timeline.ts), framework-free: a timeline is a list of
// tracks, each an element with its resting style and the keyframes it passes through at given times; the player turns
// them into looping Web Animations that run only while a quarter of the demo is on screen and the tab is visible, and
// rebuilds them when the demo's width changes. With reduced motion nothing animates and each element keeps its rest.

export type Frame = { at: number; style: Keyframe; ease?: string }
export type Track = { el: Element | null | undefined; rest: Keyframe; frames: Frame[] }
export type Timeline = { duration: number; tracks: Track[] }

/** The brand's motion, read from the tokens. */
export type Motion = {
	/** The loop's step: how long a state holds (site --dur-loop-step). */
	step: number
	/** A change between states (site --dur-loop-change). */
	change: number
	/** A row fading in (site --dur-loop-badge). */
	fade: number
	/** A quick switch (site --dur-loop-pill). */
	swap: number
	/** Between items (site --dur-seq-stagger). */
	stagger: number
	/** A flick from the last state home (site --dur-loop-flick). */
	flick: number
	/** The site's --dur-fast, --dur, --dur-move and --dur-slow. */
	fast: number
	dur: number
	move: number
	slow: number
	ease: string
	out: string
	inOut: string
}

const ms = (raw: string) => {
	const n = parseFloat(raw) || 0
	return raw.endsWith('ms') ? n : raw.endsWith('s') ? n * 1000 : n
}

export function readMotion(el: Element = document.documentElement): Motion {
	const css = getComputedStyle(el)
	const v = (name: string) => css.getPropertyValue(name).trim()
	return {
		step: ms(v('--ds-loop-step')) || 2600,
		change: ms(v('--ds-loop-change')) || 700,
		fade: ms(v('--ds-loop-badge')) || 500,
		swap: ms(v('--ds-loop-pill')) || 150,
		stagger: ms(v('--ds-seq-stagger')) || 180,
		flick: ms(v('--ds-loop-flick')) || 1400,
		fast: ms(v('--ds-duration-micro')) || 160,
		dur: ms(v('--ds-duration-enter')) || 240,
		move: ms(v('--ds-duration-glide')) || 320,
		slow: ms(v('--ds-duration-slow')) || 480,
		ease: v('--ds-easing-loop') || 'ease-in-out',
		out: v('--ds-easing-out') || 'ease-out',
		inOut: v('--ds-easing-in-out') || 'ease-in-out',
	}
}

/** A move from one style to another between two times. */
export const move = (from: number, to: number, a: Keyframe, b: Keyframe, ease: string): Frame[] => [{ at: from, style: a, ease }, { at: to, style: b }]

/** A cut from one style to another at a time. */
export const snap = (at: number, a: Keyframe, b: Keyframe): Frame[] => [{ at, style: a }, { at: at + 1, style: b }]

const RHYTHM = [64, 88, 56, 80, 72, 96, 60] as const
/** Characters appearing one by one at a typist's uneven rhythm. */
export function typing(chars: Element[], hideAt: number, startAt: number): { tracks: Track[]; end: number } {
	let t = startAt
	const tracks = chars.map((el, i) => {
		t += RHYTHM[i % RHYTHM.length]
		return { el, rest: { opacity: 1 }, frames: [...snap(hideAt, { opacity: 1 }, { opacity: 0 }), ...snap(t, { opacity: 0 }, { opacity: 1 })] }
	})
	return { tracks, end: t }
}

function build({ duration, tracks }: Timeline): Animation[] {
	const out: Animation[] = []
	for (const { el, rest, frames } of tracks) {
		if (!el) continue
		const sorted = [...frames].sort((a, b) => a.at - b.at)
		const keyframes: Keyframe[] = [
			{ ...rest, offset: 0, easing: 'linear' },
			...sorted.map((f) => ({ ...f.style, offset: Math.min(Math.max(f.at / duration, 0), 1), easing: f.ease ?? 'linear' })),
			{ ...rest, offset: 1 },
		]
		const animation = el.animate(keyframes, { duration, iterations: Infinity, fill: 'both' })
		animation.pause()
		out.push(animation)
	}
	return out
}

/** Plays `timeline` on `root` from `start` ms; returns the function that stops it. */
export function startDemo(root: HTMLElement, timeline: (root: HTMLElement, motion: Motion) => Timeline, start = 0): () => void {
	const reduce = window.matchMedia('(prefers-reduced-motion: reduce)')
	let animations: Animation[] = []
	let onScreen = false
	let time = start
	const playing = () => onScreen && document.visibilityState === 'visible'
	const sync = () => {
		for (const a of animations) {
			if (playing()) a.play()
			else a.pause()
		}
	}
	const clear = () => {
		const current = animations[0]?.currentTime
		if (typeof current === 'number') time = current
		for (const a of animations) a.cancel()
		animations = []
	}
	let near = false
	const setup = () => {
		if (!near) return
		clear()
		const loop = timeline(root, readMotion(root))
		if (reduce.matches) return
		animations = build(loop)
		for (const a of animations) a.currentTime = time
		sync()
	}
	const io = new IntersectionObserver(([entry]) => {
		onScreen = entry.isIntersecting
		sync()
	}, { threshold: 0.25 })
	const approach = new IntersectionObserver(([entry]) => {
		if (!entry.isIntersecting) return
		approach.disconnect()
		near = true
		setup()
	}, { rootMargin: '100% 0px' })
	let width = root.clientWidth
	let frame = 0
	const ro = new ResizeObserver(() => {
		if (root.clientWidth === width) return
		width = root.clientWidth
		cancelAnimationFrame(frame)
		frame = requestAnimationFrame(setup)
	})
	approach.observe(root)
	io.observe(root)
	ro.observe(root)
	document.addEventListener('visibilitychange', sync)
	reduce.addEventListener('change', setup)
	return () => {
		approach.disconnect()
		io.disconnect()
		ro.disconnect()
		cancelAnimationFrame(frame)
		document.removeEventListener('visibilitychange', sync)
		reduce.removeEventListener('change', setup)
		for (const a of animations) a.cancel()
	}
}

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
